/**
 * rules.ts — TypeScript mirror of the QuestDesk Python engine
 * (src/questdesk/text.py + src/questdesk/matcher.py).
 *
 * Disclosed scoring (0-100): keyword token recall x55 + exact 3-gram
 * phrase hit x20 + bigram Jaccard x10 + domain boost x15. The paste-a-question
 * tab runs this in the browser; data/test-vectors.json (generated by the
 * Python pipeline) keeps both implementations in exact agreement.
 */

export const STOPWORDS = new Set([
  "a", "an", "the", "and", "or", "of", "to", "in", "on", "for", "with", "by",
  "is", "are", "be", "been", "being", "was", "were", "do", "does", "did",
  "have", "has", "had", "having", "it", "its", "this", "that", "these",
  "those", "as", "at", "from", "into", "over", "under", "between", "through",
  "during", "before", "after", "above", "below", "up", "down", "out", "off",
  "about", "all", "any", "both", "each", "few", "more", "most", "other",
  "some", "such", "no", "not", "only", "own", "same", "so", "than", "too",
  "very", "can", "will", "just", "should", "now", "if", "then", "when",
  "where", "which", "who", "whom", "whose", "how", "what", "why", "there",
  "their", "they", "them", "he", "she", "we", "you", "i", "your", "our",
  "my", "me", "us", "him", "her", "his", "hers", "ours", "yours", "theirs",
  "established", "documented", "approved", "communicated", "applied",
  "evaluated", "maintained", "implemented", "defined", "reviewed", "updated",
  "least", "annually", "per", "including", "ensure", "relevant", "according",
]);

export function tokens(text: string): string[] {
  const out: string[] = [];
  for (const m of text.toLowerCase().match(/[a-z0-9]+/g) ?? []) {
    if (!STOPWORDS.has(m) && m.length > 1) out.push(m);
  }
  return out;
}

export function tokenSet(text: string): Set<string> {
  return new Set(tokens(text));
}

export function bigrams(text: string): Set<string> {
  const toks = tokens(text);
  const out = new Set<string>();
  for (let i = 0; i + 1 < toks.length; i++) out.add(toks[i] + " " + toks[i + 1]);
  return out;
}

export function jaccard(a: Set<string>, b: Set<string>): number {
  if (a.size === 0 && b.size === 0) return 1;
  if (a.size === 0 || b.size === 0) return 0;
  let inter = 0;
  for (const x of a) if (b.has(x)) inter++;
  return inter / (a.size + b.size - inter);
}

export interface AnswerLite {
  id: string;
  domains: string[];
  keywords: string;
  text: string;
  response: string;
  owner: string;
  owner_title: string;
  last_reviewed: string;
  evidence: string[];
}

export interface ScoreBreakdown {
  score: number;
  parts: { keyword_recall: number; exact_phrase: number; bigram_jaccard: number; domain_boost: number };
}

export interface Weights {
  keyword_recall: number;
  exact_phrase: number;
  bigram_jaccard: number;
  domain_boost: number;
}

export const DEFAULT_WEIGHTS: Weights = {
  keyword_recall: 55,
  exact_phrase: 20,
  bigram_jaccard: 10,
  domain_boost: 15,
};

function round2(x: number): number {
  return Math.round(x * 100) / 100;
}

function answerCorpus(a: AnswerLite): string {
  return `${a.text} ${a.keywords}`;
}

export function scorePair(
  question: string,
  qDomain: string,
  answer: AnswerLite,
  weights: Weights = DEFAULT_WEIGHTS,
): ScoreBreakdown {
  const qToks = tokenSet(question);
  const aToks = tokenSet(answerCorpus(answer));
  let inter = 0;
  for (const t of qToks) if (aToks.has(t)) inter++;
  const recall = qToks.size > 0 ? inter / qToks.size : 0;
  const keywordScore = recall * weights.keyword_recall;

  const kwToks = tokens(answer.keywords);
  const qLow = question.toLowerCase();
  let phraseHit = 0;
  for (let i = 0; i + 2 < kwToks.length; i++) {
    const phrase = kwToks[i] + " " + kwToks[i + 1] + " " + kwToks[i + 2];
    if (qLow.includes(phrase)) {
      phraseHit = 1;
      break;
    }
  }
  const phraseScore = phraseHit * weights.exact_phrase;

  const bigramScore = jaccard(bigrams(question), bigrams(answerCorpus(answer))) * weights.bigram_jaccard;
  const domainScore = answer.domains.includes(qDomain) ? weights.domain_boost : 0;

  return {
    score: round2(keywordScore + phraseScore + bigramScore + domainScore),
    parts: {
      keyword_recall: round2(keywordScore),
      exact_phrase: round2(phraseScore),
      bigram_jaccard: round2(bigramScore),
      domain_boost: round2(domainScore),
    },
  };
}

export interface MatchResult {
  answerId: string | null;
  score: number;
  parts: ScoreBreakdown["parts"];
  margin: number;
  answer: AnswerLite | null;
}

/** Best-answer match for one question. Mirrors Python match_question. */
export function matchQuestion(
  question: string,
  qDomain: string,
  answers: AnswerLite[],
  minMatch: number,
  weights: Weights = DEFAULT_WEIGHTS,
): MatchResult {
  let best: AnswerLite | null = null;
  let bestScore: ScoreBreakdown | null = null;
  let second = 0;
  for (const a of answers) {
    const s = scorePair(question, qDomain, a, weights);
    if (!bestScore || s.score > bestScore.score) {
      second = bestScore ? bestScore.score : 0;
      best = a;
      bestScore = s;
    } else if (s.score > second) {
      second = s.score;
    }
  }
  const score = bestScore ? bestScore.score : 0;
  const ok = best !== null && score >= minMatch;
  return {
    answerId: ok && best ? best.id : null,
    score,
    parts: bestScore ? bestScore.parts : { keyword_recall: 0, exact_phrase: 0, bigram_jaccard: 0, domain_boost: 0 },
    margin: round2(score - second),
    answer: ok ? best : null,
  };
}

export type Route = "READY" | "REVIEW" | "REVERIFY" | "NEW";

/** Route prediction for the paste tab. Mirrors the Python freshness+route nodes. */
export function routeFor(
  m: MatchResult,
  replayDate: string,
  answerStaleAfterDays: number,
  autoReady: number,
): { route: Route; flags: string[] } {
  const flags: string[] = [];
  if (!m.answer || !m.answerId) return { route: "NEW", flags };
  const replay = new Date(replayDate + "T00:00:00Z").getTime();
  const reviewed = new Date(m.answer.last_reviewed + "T00:00:00Z").getTime();
  const ageDays = Math.round((replay - reviewed) / 86400000);
  if (ageDays > answerStaleAfterDays) flags.push("STALE_ANSWER");
  if (flags.length > 0) return { route: "REVERIFY", flags };
  if (m.score >= autoReady) return { route: "READY", flags };
  return { route: "REVIEW", flags };
}
